1	import Link from "next/link";
2	import { Reveal } from "@/components/marketing/Reveal";
3	import { Section, SectionTitle, PageHero } from "@/components/marketing/primitives";
4	import { CtaBand } from "@/components/marketing/sections";
5	import { FaqJsonLd, ProductOffersJsonLd, APP_URL } from "@/components/marketing/StructuredData";
6	import { GameHero } from "@/components/marketing/GameHero";
7	
8	/**
9	 * Shared layout for the game-server / gaming-VPS SEO landing pages.
10	 *
11	 * It renders the EXACT same markup as the hand-written /rust-server-hosting and
12	 * /minecraft-server-hosting pages (hero → intro prose → plans → why → steps →
13	 * guides → FAQ → related → CTA) so every new page reads as native. Each route
14	 * file owns its own `export const metadata` (Next requires it in the page file)
15	 * and passes real, game-specific copy + real Nxeon pricing in here.
16	 */
17	
18	export type Cta = { label: string; href: string };
19	export type Plan = {
20	  /** Full heading, e.g. "16 GB" or "Max · 16 GB". */
21	  name: string;
22	  /** Displayed price, e.g. "$14.99". Rendered with a trailing "/mo". */
23	  price: string;
24	  /** Small right-aligned meta, e.g. "32 players" or "recommended". */
25	  meta?: string;
26	  blurb: string;
27	  popular?: boolean;
28	};
29	export type Link2 = { label: string; href: string };
30	
31	export type GameLandingProps = {
32	  /**
33	   * Canonical game family (lib/games.ts GAME_FAMILIES). When set, the hero shows
34	   * that game's <GameLogo>. Omit for non-family pages (e.g. Gaming VPS) to keep
35	   * the plain hero.
36	   */
37	  family?: string;
38	  hero: {
39	    eyebrow?: string;
40	    title: string;
41	    highlight?: string;
42	    sub: string;
43	    primary?: Cta;
44	    secondary?: Cta;
45	  };
46	  /** Intro prose paragraphs (2–3). */
47	  intro: React.ReactNode[];
48	  plansTitle: string;
49	  plansSub: string;
50	  /** Where every plan card's button links, and its label. */
51	  plansCta: Cta;
52	  plans: Plan[];
53	  whyTitle: string;
54	  why: { title: string; body: string }[];
55	  stepsTitle: string;
56	  steps: { title: string; body: string }[];
57	  /** Optional "Related guides" — internal links to the matching blog posts. */
58	  guides?: Link2[];
59	  faq: { q: string; a: string }[];
60	  related: Link2[];
61	};
62	
63	export function GameLandingPage(props: GameLandingProps) {
64	  const {
65	    family,
66	    hero,
67	    intro,
68	    plansTitle,
69	    plansSub,
70	    plansCta,
71	    plans,
72	    whyTitle,
73	    why,
74	    stepsTitle,
75	    steps,
76	    guides,
77	    faq,
78	    related,
79	  } = props;
80	
81	  // Absolute URL for the offers — plansCta.href is where each plan card buys.
82	  const offerUrl = plansCta.href.startsWith("http") ? plansCta.href : `${APP_URL}${plansCta.href}`;
83	
84	  return (
85	    <>
86	      <FaqJsonLd items={faq} />
87	      {plans.length > 0 && (
88	        <ProductOffersJsonLd
89	          name={hero.title}
90	          description={hero.sub}
91	          url={offerUrl}
92	          // Plan prices are display strings like "$14.99" — strip to a number.
93	          offers={plans.map((p) => ({
94	            name: p.name,
95	            price: parseFloat(p.price.replace(/[^0-9.]/g, "")),
96	          }))}
97	        />
98	      )}
99	
100	      {family ? (
101	        <GameHero
102	          family={family}
103	          eyebrow={hero.eyebrow ?? "Game servers"}
104	          title={hero.title}
105	          highlight={hero.highlight}
106	          sub={hero.sub}
107	          primary={hero.primary}
108	          secondary={hero.secondary}
109	        />
110	      ) : (
111	        <PageHero
112	          eyebrow={hero.eyebrow ?? "Game servers"}
113	          title={hero.title}
114	          highlight={hero.highlight}
115	          sub={hero.sub}
116	          primary={hero.primary}
117	          secondary={hero.secondary}
118	        />
119	      )}
120	
121	      {/* Intro prose */}
122	      <Section tone="base" size="md">
123	        <div className="mx-auto max-w-3xl space-y-4 text-[15px] leading-relaxed text-slate-300">
124	          {intro.map((p, i) => (
125	            <Reveal as="p" key={i} delay={i * 60}>
126	              {p}
127	            </Reveal>
128	          ))}
129	        </div>
130	      </Section>
131	
132	      {/* Plans */}
133	      <Section tone="panel" size="lg">
134	        <SectionTitle eyebrow="Plans" title={plansTitle} sub={plansSub} />
135	        <div className="mt-10 grid gap-4 sm:grid-cols-2 lg:grid-cols-3">
136	          {plans.map((p, i) => (
137	            <Reveal
138	              key={p.name}
139	              delay={i * 60}
140	              className={`card relative ${p.popular ? "ring-1 ring-brand-400/40" : ""}`}
141	            >
142	              {p.popular && (
143	                <span className="absolute -top-3 left-1/2 -translate-x-1/2 rounded-full bg-brand-500/20 px-3 py-1 text-[11px] font-semibold uppercase tracking-wider text-brand-200">
144	                  Most popular
145	                </span>
146	              )}
147	              <div className="flex items-baseline justify-between">
148	                <h3 className="text-lg font-semibold text-white">{p.name}</h3>
149	                {p.meta && <span className="text-xs font-medium text-slate-500">{p.meta}</span>}
150	              </div>
151	              <p className="mt-3">
152	                <span className="text-3xl font-bold text-white">{p.price}</span>
153	                <span className="text-sm text-slate-500">/mo</span>
154	              </p>
155	              <p className="mt-3 text-sm leading-relaxed text-slate-400">{p.blurb}</p>
156	              <Link
157	                href={plansCta.href}
158	                className={`mt-5 block rounded-xl px-4 py-2.5 text-center text-sm font-semibold ${
159	                  p.popular ? "btn-primary" : "btn-secondary"
160	                }`}
161	              >
162	                {plansCta.label}
163	              </Link>
164	            </Reveal>
165	          ))}
166	        </div>
167	      </Section>
168	
169	      {/* Why Nxeon */}
170	      <Section tone="base" size="md">
171	        <SectionTitle eyebrow="Why Nxeon" title={whyTitle} />
172	        <div className="mt-10 grid gap-4 sm:grid-cols-2 lg:grid-cols-3">
173	          {why.map((w, i) => (
174	            <Reveal key={w.title} delay={i * 60} className="card">
175	              <h3 className="text-base font-semibold text-white">{w.title}</h3>
176	              <p className="mt-2 text-sm leading-relaxed text-slate-400">{w.body}</p>
177	            </Reveal>
178	          ))}
179	        </div>
180	      </Section>
181	
182	      {/* Steps */}
183	      <Section tone="panel" size="md">
184	        <SectionTitle eyebrow="Get started" title={stepsTitle} />
185	        <ol className="mx-auto mt-10 max-w-3xl space-y-3">
186	          {steps.map((s, i) => (
187	            <Reveal as="li" key={s.title} delay={i * 60} className="card flex gap-4">
188	              <span className="flex h-8 w-8 flex-none items-center justify-center rounded-lg bg-brand-500/20 text-sm font-bold text-brand-200">
189	                {i + 1}
190	              </span>
191	              <div>
192	                <h3 className="text-sm font-semibold text-white">{s.title}</h3>
193	                <p className="mt-1 text-sm leading-relaxed text-slate-400">{s.body}</p>
194	              </div>
195	            </Reveal>
196	          ))}
197	        </ol>
198	      </Section>
199	
200	      {/* Related guides (internal links to matching blog posts) */}
201	      {guides && guides.length > 0 && (
202	        <Section tone="base" size="md">
203	          <SectionTitle
204	            eyebrow="Guides"
205	            title="Step-by-step setup guides"
206	            sub="Prefer to run it yourself, or just want to understand the specs? These walkthroughs cover it."
207	          />
208	          <div className="mx-auto mt-10 grid max-w-3xl gap-3 sm:grid-cols-2">
209	            {guides.map((g) => (
210	              <Link
211	                key={g.href}
212	                href={g.href}
213	                className="card card-hover flex items-center justify-between gap-3 text-sm font-medium text-slate-200"
214	              >
215	                {g.label}
216	                <span className="text-brand-300">→</span>
217	              </Link>
218	            ))}
219	          </div>
220	        </Section>
221	      )}
222	
223	      {/* FAQ */}
224	      <Section tone={guides && guides.length > 0 ? "panel" : "base"} size="md">
225	        <SectionTitle eyebrow="FAQ" title="Questions, answered" />
226	        <div className="mx-auto mt-10 max-w-3xl space-y-3">
227	          {faq.map((f) => (
228	            <details key={f.q} className="card group">
229	              <summary className="cursor-pointer list-none font-medium text-white marker:content-none">
230	                <span className="flex items-center justify-between gap-4">
231	                  {f.q}
232	                  <span className="text-slate-500 transition-transform group-open:rotate-45">+</span>
233	                </span>
234	              </summary>
235	              <p className="mt-3 text-sm leading-relaxed text-slate-400">{f.a}</p>
236	            </details>
237	          ))}
238	        </div>
239	      </Section>
240	
241	      {/* Related */}
242	      <Section tone="base" size="sm">
243	        <div className="mx-auto flex max-w-3xl flex-wrap items-center justify-center gap-2">
244	          <span className="text-xs font-semibold uppercase tracking-wider text-slate-500">Related</span>
245	          {related.map((r) => (
246	            <Link
247	              key={r.href}
248	              href={r.href}
249	              className="rounded-full border border-white/10 bg-white/[0.03] px-3 py-1 text-sm text-slate-300 transition-colors hover:border-white/20 hover:text-white"
250	            >
251	              {r.label}
252	            </Link>
253	          ))}
254	        </div>
255	      </Section>
256	
257	      <Section tone="deep" size="lg">
258	        <CtaBand />
259	      </Section>
260	    </>
261	  );
262	}
